BY_KEY = {t["key"]: t for t in T}


def fill(text: str, c: dict, extra: dict) -> str:
    return text.format(first=c["name"].split()[0], company=c["company"], seats=c.get("seats", 0), **extra)


def script(tpl: dict, c: dict, extra: dict, rewrite: bool) -> list[str]:
    out = [json.dumps({"category": tpl["cat"], "urgency": tpl["urg"], "summary": tpl["summary"]})]
    if tpl["cat"] == "other":
        return out
    out += [fill(tpl["notes"], c, extra), fill(tpl["draft"], c, extra)]
    if rewrite and tpl.get("reject"):
        out += [json.dumps({"approved": False, "problems": [tpl["reject"]]}), fill(tpl["redraft"], c, extra), OK]
    else:
        out.append(OK)
    return out


def customer_for(tpl: dict, rng: random.Random) -> dict:
    if tpl.get("new"):
        email, name, company = tpl["new"]
        return {"email": email, "name": name, "company": company, "seats": 0}
    if tpl.get("who"):
        return BY_EMAIL[tpl["who"][0]]
    pool = [c for c in CUSTOMERS if not tpl.get("plan") or c["plan"] in tpl["plan"]]
    return rng.choice(pool)


def work_time(base: dt.datetime, rng: random.Random) -> dt.datetime:
    t = base.replace(hour=rng.randint(8, 18), minute=rng.randint(0, 59), second=rng.randint(0, 59))
    if t.weekday() >= 5 and rng.random() < 0.7:
        t -= dt.timedelta(days=t.weekday() - 4)
    return t


def make(sb, tpl: dict, rng: random.Random, received: dt.datetime, rewrite: bool = False, decision: str | None = None,
         decided_after: int = 30) -> dict:
    c = customer_for(tpl, rng)
    extra = {"less": max(1, int(c.get("seats", 4) * 0.6))}
    t = sb.new_ticket(c["email"], tpl["subject"], fill(tpl["body"], c, extra), received)
    if t["sender"] not in BY_EMAIL:
        t["name"], t["company"] = c["name"], c["company"]
    sb.llm.script = script(tpl, c, extra, rewrite)
    try:
        sb.start(t, at=received + dt.timedelta(seconds=rng.randint(5, 40)))
    finally:
        sb.llm.script = None
    when = received + dt.timedelta(minutes=decided_after)
    if decision == "approve":
        sb.decide(t, "approve", at=when, by=rng.choice(["Sam", "Priya", "Jonas"]))
    elif decision == "edit":
        draft = sb.pending(t)["draft"]
        sb.decide(t, "edit", draft.replace("The Support Team", "Best,\nSam from Lumen Support"), at=when, by="Sam")
    elif decision == "reject":
        sb.decide(t, "reject", at=when, by=rng.choice(["Priya", "Jonas"]))
    elif decision == "staff":
        sb.staff_answer(t, f"Hi {c['name'].split()[0]},\n\nThanks for reaching out. I've passed this to the right team and they'll be in "
                           "touch within one business day.\n\nJonas, Lumen Support", by="Jonas", at=when)
    return t


def populate(sb) -> None:
    rng = random.Random(11)
    today = now()
    keys = [k for k in BY_KEY]
    weights = {"dup": 1, "vat": 3, "refund": 3, "failed": 1, "csv": 3, "sso": 3, "api": 3, "share": 3, "2fa": 3, "hook": 3,
               "quote": 1, "seats": 3, "nonprofit": 1, "gdpr": 1, "partner": 1}
    # History: resolved tickets from the last 14 days.
    history = []
    for days_ago in range(14, 0, -1):
        day = today - dt.timedelta(days=days_ago)
        for _ in range(rng.randint(3, 7) if day.weekday() < 5 else rng.randint(0, 2)):
            history.append((work_time(day, rng), rng.choices(keys, [weights[k] for k in keys])[0]))
    for received, key in sorted(history):
        tpl = BY_KEY[key]
        if tpl["cat"] == "other":
            make(sb, tpl, rng, received, decision="staff", decided_after=rng.randint(40, 300))
            continue
        decision = rng.choices(["approve", "edit", "reject"], [76, 18, 6])[0]
        make(sb, tpl, rng, received, rewrite=rng.random() < 0.5, decision=decision, decided_after=rng.randint(4, 95))

    # Right now: drafts waiting for a person, one escalation, and fresh emails nobody has run yet.
    recent = lambda mins: today - dt.timedelta(minutes=mins)  # noqa: E731
    make(sb, BY_KEY["dup"], rng, recent(26), rewrite=True)
    make(sb, BY_KEY["sso"], rng, recent(48))
    make(sb, BY_KEY["nonprofit"], rng, recent(71), rewrite=True)
    make(sb, BY_KEY["seats"], rng, recent(95))
    make(sb, BY_KEY["gdpr"], rng, recent(130))
    for mins, (sender, subject, body) in [
        (3, ("tom@harbortech.io", "weird characters after import",
             "Imported our contact list from Excel and all the names with accents look like \"JosÃ©\". What did we do wrong?")),
        (9, ("priya@northfieldlogistics.com", "Pricing for 120 users",
             "We're evaluating tools for 120 people and need SSO and audit logs. What would that cost on an annual plan?\n\nPriya")),
        (14, ("noah@pebblefinance.co", "API returning 429",
              "Hi team, since yesterday our data pipeline gets HTTP 429 from your API every night around 2am. We push about 3,000 events "
              "one by one. Is something wrong on your side?\n\nNoah")),
    ]:
        t = sb.new_ticket(sender, subject, body, recent(mins))
        if sender == "priya@northfieldlogistics.com":
            t["name"], t["company"] = "Priya Shah", "Northfield Logistics"
